                GenerateMaterial: function (shaderName, materialName, texture) {
                    //创建材质球
                    var shader = UnityEngine.Shader.Find(shaderName);
                    var material = new UnityEngine.Material.$ctor2(shader);
                    material.name = materialName;
                    material.mainTexture = texture;

                    return material;
                },
                /*DragonBones.UnityFactoryHelper.GenerateMaterial:static end.*/

                /*DragonBones.UnityFactoryHelper.CheckResourecdPath:static start.*/
                /**
                 * 检查路径合法性
                 *
                 * @static
                 * @this DragonBones.UnityFactoryHelper
                 * @memberof DragonBones.UnityFactoryHelper
                 * @param   {string}    path
                 * @return  {string}
                 */
                CheckResourecdPath: function (path) {
                    var index = path.lastIndexOf("Resources");
                    if (index > 0) {
                        path = path.substr(((index + 10) | 0));
                    }

                    index = path.lastIndexOf(".");
                    if (index > 0) {
                        path = path.substr(0, index);
                    }

                    return path;
                },
                /*DragonBones.UnityFactoryHelper.CheckResourecdPath:static end.*/

                /*DragonBones.UnityFactoryHelper.GetTextureAtlasImagePath:static start.*/
                /**
                 * 根据贴图JSON文件的路径和JSON文件中贴图名称获得贴图路径
                 *
                 * @static
                 * @this DragonBones.UnityFactoryHelper
                 * @memberof DragonBones.UnityFactoryHelper
                 * @param   {string}    textureAtlasJSONPath     贴图JSON文件路径:NewDragon/NewDragon_tex
                 * @param   {string}    textureAtlasImageName    贴图名称:NewDragon.png
                 * @return  {string}
                 */
                GetTextureAtlasImagePath: function (textureAtlasJSONPath, textureAtlasImageName) {
                    var index = textureAtlasJSONPath.lastIndexOf("Resources");
                    if (index > 0) {
                        textureAtlasJSONPath = textureAtlasJSONPath.substr(((index + 10) | 0));
                    }

                    index = textureAtlasJSONPath.lastIndexOf("/");

                    var textureAtlasImagePath = textureAtlasImageName;
                    if (index > 0) {
                        textureAtlasImagePath = (textureAtlasJSONPath.substr(0, ((index + 1) | 0)) || "") + (textureAtlasImageName || "");
                    }

                    index = textureAtlasImagePath.lastIndexOf(".");
                    if (index > 0) {
                        textureAtlasImagePath = textureAtlasImagePath.substr(0, index);
                    }

                    return textureAtlasImagePath;
                },
                /*DragonBones.UnityFactoryHelper.GetTextureAtlasImagePath:static end.*/

                /*DragonBones.UnityFactoryHelper.GetTextureAtlasNameByPath:static start.*/
                /**
                 * 根据贴图路径获得贴图名称
                 *
                 * @static
                 * @this DragonBones.UnityFactoryHelper
                 * @memberof DragonBones.UnityFactoryHelper
                 * @param   {string}    textureAtlasJSONPath
                 * @return  {string}
                 */
                GetTextureAtlasNameByPath: function (textureAtlasJSONPath) {
                    var name = "";
                    var index = (textureAtlasJSONPath.lastIndexOf("/") + 1) | 0;
                    var lastIdx = textureAtlasJSONPath.lastIndexOf("_tex");

                    if (lastIdx > -1) {
                        if (lastIdx > index) {
                            name = textureAtlasJSONPath.substr(index, ((lastIdx - index) | 0));
                        } else {
                            name = textureAtlasJSONPath.substr(index);
                        }
                    } else {
                        if (index > -1) {
                            name = textureAtlasJSONPath.substr(index);
                        }

                    }

                    return name;
                },
